# Let's test various corner patches to find the backdoor trigger
# We'll create test images with different patch types in different corners
import torch

def create_patch_image(patch_type="white", corner="top_left", patch_size=4):
    """Create a clean image with a patch in the specified corner."""
    # Start with a clean image (first clean image)
    img = x_clean[0:1].clone().float() / 255.0

    # Denormalize to add patch in pixel space, then renormalize
    mean = torch.tensor([0.4914, 0.4822, 0.4465]).view(1, 3, 1, 1)
    std = torch.tensor([0.2470, 0.2435, 0.2616]).view(1, 3, 1, 1)

    img_denorm = img * std + mean

    h, w = 32, 32
    margin = 1

    if corner == "top_left":
        y_start, x_start = margin, margin
    elif corner == "top_right":
        y_start, x_start = margin, w - margin - patch_size
    elif corner == "bottom_left":
        y_start, x_start = h - margin - patch_size, margin
    elif corner == "bottom_right":
        y_start, x_start = h - margin - patch_size, w - margin - patch_size

    y_end = y_start + patch_size
    x_end = x_start + patch_size

    if patch_type == "white":
        patch = torch.ones(1, 3, patch_size, patch_size)
    elif patch_type == "checkerboard":
        patch = torch.zeros(1, 3, patch_size, patch_size)
        for i in range(patch_size):
            for j in range(patch_size):
                if (i + j) % 2 == 0:
                    patch[:, :, i, j] = 1.0
    elif patch_type == "random":
        patch = torch.randint(0, 2, (1, 3, patch_size, patch_size)).float()
    elif patch_type == "black":
        patch = torch.zeros(1, 3, patch_size, patch_size)

    img_denorm[:, :, y_start:y_end, x_start:x_end] = patch

    # Renormalize
    img_norm = (img_denorm - mean) / std
    return img_norm * 255  # back to 0-255 range for forward()

